param([int]$Port=9501)
$ErrorActionPreference='Stop';$edge='C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe';$profile=Join-Path $env:TEMP "curdun-post-p16-stock-$Port";$proc=Start-Process $edge -ArgumentList @('--headless','--disable-gpu','--disable-extensions','--no-first-run','--remote-allow-origins=*',"--remote-debugging-port=$Port","--user-data-dir=$profile",'http://localhost:8000/app.html') -WindowStyle Hidden -PassThru;$ws=$null
try{$page=$null;for($i=0;$i-lt60-and!$page;$i++){Start-Sleep -Milliseconds 200;try{foreach($c in (Invoke-RestMethod "http://localhost:$Port/json/list")){if($c.type-eq'page'-and$c.url-like'http://localhost:8000/*'){$page=$c;break}}}catch{}};if(!$page){throw'No page'};$ws=[Net.WebSockets.ClientWebSocket]::new();$ws.ConnectAsync([Uri]$page.webSocketDebuggerUrl,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null
$js=@'
(async()=>{const pause=ms=>new Promise(r=>setTimeout(r,ms));const wait=async(fn,l)=>{for(let i=0;i<150;i++){const v=fn();if(v)return v;await pause(100)}throw Error('Timeout '+l)};await wait(()=>typeof posPinLogin==='function','scripts');await posPinLogin('2468',8,1);await posBootstrap();const report=await posApiFetch('/pos/reports?from=2026-08-22&to=2026-08-22');const products={low:posCountLowStock(),out:posCountOutOfStock(),conditions:POS_PRODUCTS.filter(p=>posStockStatus(p)!=='OK').map(p=>({id:p.id,name:p.name,company_id:p.companyId,stock:p.stock,minimum:p.minimumStock,status:p.stockStatus,needed:p.needed}))};const alerts={rows:S.posStockAlerts.length,low:S.posStockAlerts.filter(a=>a.severity==='low').length,out:S.posStockAlerts.filter(a=>a.severity==='out').length,unread:S.posStockAlerts.filter(a=>Number(a.unread)).length,open:S.posStockAlerts.filter(a=>Number(a.open_notification)).length,items:S.posStockAlerts};const hostProducts=document.createElement('div');hostProducts.innerHTML=renderPOSProducts();const productText=hostProducts.textContent.replace(/\s+/g,' ').trim();const hostAlerts=document.createElement('div');hostAlerts.innerHTML=renderPOSNotifications();const alertText=hostAlerts.textContent.replace(/\s+/g,' ').trim();const session32=await posApiFetch('/pos/sessions/32/summary');const result={cashier:S.posActiveUser.name,company:S.posActiveUser.company_id||2,branch:S.posActiveUser.branchId,products,dashboard:{total:Number(S.posDashData.products),normal:Number(S.posDashData.normal_stock),low:Number(S.posDashData.low_stock),out:Number(S.posDashData.out_of_stock),cost:Number(S.posDashData.inventory_cost_value),retail:Number(S.posDashData.inventory_retail_value),scope:S.posDashData.inventory_scope},stockReport:{total:Number(report.summary.total_products),normal:Number(report.summary.normal_products),low:Number(report.summary.low_stock_products),out:Number(report.summary.out_of_stock_products),cost:Number(report.summary.inventory_cost_value),retail:Number(report.summary.inventory_retail_value),scope:report.summary.inventory_scope,inventory:report.inventory.filter(p=>p.stock_status!=='NORMAL')},alerts,session32:{id:session32.session.id,state:session32.session.state,expected:Number(session32.expected_cash),counted:Number(session32.cash_reconciliation.counted_cash),difference:Number(session32.cash_reconciliation.difference)},visible:{products:productText,alerts:alertText}};if(products.low!==result.dashboard.low||products.out!==result.dashboard.out||result.dashboard.low!==result.stockReport.low||result.dashboard.out!==result.stockReport.out||alerts.low!==products.low||alerts.out!==products.out||alerts.rows!==products.low+products.out)throw Error('Cross-view inventory mismatch '+JSON.stringify(result));if(result.dashboard.total!==result.dashboard.normal+result.dashboard.low+result.dashboard.out||result.dashboard.total!==result.stockReport.total||result.dashboard.cost!==result.stockReport.cost||result.dashboard.retail!==result.stockReport.retail)throw Error('Inventory summary mismatch '+JSON.stringify(result));if(result.dashboard.scope.basis!=='company_wide'||result.stockReport.scope.company_id!==result.dashboard.scope.company_id)throw Error('Inventory scope mismatch');if(!productText.includes('Inventory cost value')||!alertText.includes('notification'))throw Error('Inventory labels missing');if(result.session32.state!=='CLOSED'||result.session32.expected!==258.93||result.session32.counted!==258.93||result.session32.difference!==0)throw Error('P1-P16 baseline changed');return result;})()
'@;$m=@{id=1;method='Runtime.evaluate';params=@{expression=$js;awaitPromise=$true;returnByValue=$true}}|ConvertTo-Json -Depth 8 -Compress;$bytes=[Text.Encoding]::UTF8.GetBytes($m);$ws.SendAsync([ArraySegment[byte]]::new($bytes),[Net.WebSockets.WebSocketMessageType]::Text,$true,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null;while(1){$buf=New-Object byte[] 1048576;$x=$ws.ReceiveAsync([ArraySegment[byte]]::new($buf),[Threading.CancellationToken]::None).GetAwaiter().GetResult();$r=([Text.Encoding]::UTF8.GetString($buf,0,$x.Count)|ConvertFrom-Json);if($r.id-eq1){if($r.result.exceptionDetails){throw($r.result.exceptionDetails|ConvertTo-Json -Depth 12)};$r.result.result.value|ConvertTo-Json -Depth 30;break}}}finally{if($ws){$ws.Dispose()};if($proc-and!$proc.HasExited){Stop-Process $proc.Id -Force}}
